// Writes supabase/seed.sql from the content that ships with the app.
//
//   npm run db:seed
//
// Run the generated file in the Supabase SQL editor after schema.sql and
// admin.sql. It only adds rows that are not there yet, so running it again
// never overwrites what an administrator has since edited.
import { readFileSync, writeFileSync } from 'node:fs';
import { destinations } from '@/data/destinations';
import { events } from '@/data/events';
import { festivals } from '@/data/festivals';
import { regions } from '@/data/regions';
import { transportation } from '@/data/transportation';
import {
  destinationToRow,
  eventToRow,
  festivalToRow,
  regionToRow,
  transportToRow,
  type ContentTable,
} from '@/services/content/resources';

const literal = (value: unknown): string => {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'number') return String(value);
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  if (typeof value === 'object') return `'${JSON.stringify(value).replace(/'/g, "''")}'::jsonb`;
  return `'${String(value).replace(/'/g, "''")}'`;
};

const insert = (table: ContentTable, rows: object[]): string => {
  if (rows.length === 0) return '';
  const columns = Object.keys(rows[0]);
  const values = rows
    .map((row) => `  (${columns.map((c) => literal((row as Record<string, unknown>)[c])).join(', ')})`)
    .join(',\n');
  return (
    `-- ${table}: ${rows.length} rows\n` +
    `insert into public.${table} (${columns.join(', ')}) values\n${values}\n` +
    `on conflict (id) do nothing;\n`
  );
};

const sql = [
  '-- YenkoGH starting content. Generated by `npm run db:seed`; do not edit by hand.',
  '-- Run after schema.sql and admin.sql. Existing rows are left untouched.',
  '',
  'begin;',
  '',
  insert('regions', regions.map((r, i) => regionToRow(r, i))),
  insert('destinations', destinations.map((d, i) => destinationToRow(d, i, regions))),
  insert('events', events.map((e, i) => eventToRow(e, i, regions))),
  insert('festivals', festivals.map((f, i) => festivalToRow(f, i, regions))),
  insert('transport_options', transportation.map((t, i) => transportToRow(t, i))),
  'commit;',
  '',
].join('\n');

writeFileSync('supabase/seed.sql', sql);

// One file to paste into the SQL editor for a brand-new project: the three scripts in order
writeFileSync(
  'supabase/setup.sql',
  [
    '-- YenkoGH complete database setup: schema.sql + admin.sql + seed.sql, in that order.',
    '-- Generated by `npm run db:seed`; edit those three files, not this one.',
    '-- Paste the whole file into the Supabase SQL editor and run it once. Safe to run again.',
    '',
    readFileSync('supabase/schema.sql', 'utf8'),
    readFileSync('supabase/admin.sql', 'utf8'),
    sql,
  ].join('\n'),
);
console.log(
  `supabase/seed.sql written: ${regions.length} regions, ${destinations.length} destinations, ` +
    `${events.length} events, ${festivals.length} festivals, ${transportation.length} transport options`,
);
